// Classic only, CO-7: the Classic half of hr-v2-dashboard.test.mjs, kept when its V2 page was removed. Generated by stripping
// every statement that read a deleted V2 file, then retitled for Classic; no assertion was added or changed.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
const read = (path) =>
    readFileSync(new URL(`../../${path}`, import.meta.url), 'utf8');
const classic = read('resources/js/pages/HR/Dashboard.vue');
const composable = read('resources/js/composables/hr/useDashboardPage.ts');

test('Classic HR dashboard reads through useDashboardPage', () => {
    assert.match(classic, /useDashboardPage\(props\)/);
    assert.match(composable, /router\.get\(\s*'\/hr\/dashboard'/);
});

test('the dashboard composable only reads', () => {
    assert.doesNotMatch(composable, /router\.(post|put|patch|delete)/);
});

test('Classic HR dashboard uses no V2 part', () => {
    assert.doesNotMatch(classic, /V2WorkLayout|V2Stat/);
});
